    'msg.ent.legal_notice_full': 'قواعد احتساب المستحقات المعتمدة في نظام المنار: أجر الاستحقاق = الراتب الشهري المسجّل للموظف وحده — لا بدلات ولا مكافآت ولا منح ولا أي مزايا نقدية دورية. الأجر اليومي = الراتب الشهري ÷ 26، وهي قاعدة الاحتساب المعتمدة في النظام. الإجازة السنوية 30 يومًا عن كل سنة خدمة. تبدأ الأهلية بعد إتمام 6 أشهر خدمة، وهي بوابة أهلية لا فترة مخصومة: قبل إتمامها لا يُستحق شيء، وبعدها يُحتسب الرصيد تناسبيًا من تاريخ التعيين الأصلي حتى تاريخ الاحتساب المعروض (تُحتسب أجزاء السنة بنسبتها). مدة الخدمة تُحسب بالأيام التقويمية، فلا تتغيّر القيم بتغيّر وقت فتح الكشف خلال اليوم. دفعات المستحقات تُخفّض الرصيد المالي المتبقي فقط: لا تستهلك أيام إجازة، ولا تُعدّل سجلات الإجازة، ولا تؤثّر في الرواتب أو المحاسبة. مكافأة نهاية الخدمة قيمة تقديرية إخبارية تبقى خارج المستحق القابل للدفع، ولا تُصرف إلا عبر مسار التسوية النهائية المعتمد (غير متاح في هذا الإصدار). هذه الأرقام ليست بديلاً عن التسوية النهائية الرسمية المعتمدة.',

