    'msg.ent.legal_notice_full': 'Approved manarERP entitlement calculation rules: the entitlement wage is the recorded monthly salary of the employee only - no allowances, bonuses, grants, or recurring monetary benefits. Daily wage = monthly salary / 26, the approved calculation rule used by the system. Annual leave is 30 days per year of service. Eligibility begins after 6 completed months and is an eligibility gate, not a deducted period: nothing is earned before it, and once it opens the balance accrues proportionally from the original hire date to the displayed calculation date (partial years count pro rata). Service duration is counted in calendar days, so the figures do not change with the time of day the statement is opened. Entitlement payments reduce only the remaining financial balance: they consume no leave days, modify no leave records, and affect neither payroll nor accounting. The end-of-service gratuity is an informational estimate that stays outside the payable balance and is disbursable only through the approved final-settlement workflow (not available in this release). These figures are not a substitute for the officially approved final settlement.',

