export function t(key: string, lang: Lang, vars?: Record<string, string | number>): string {
  let str = DICT[lang][key] ?? DICT.ar[key] ?? key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      str = str.replaceAll(`{${k}}`, String(v));
    }
  }
  return str;
}

/**
 * مترجم الواجهة — **هويّته مستقرّة** ما دامت اللغة كما هي.
 *
 * كانت تُعيد كائنًا ودالّة جديدين في **كل رسم**. هذا يجعل `t` اعتمادية غير
 * مستقرّة: أي `useEffect`/`useMemo`/`useCallback` يضعها في مصفوفة اعتمادياته —
 * وهو ما تفرضه قاعدة `react-hooks/exhaustive-deps` — يُعاد تشغيله في كل رسم. وإن
 * كان ذلك التأثير يضبط حالة (تحميل/بيانات) صار الأمر حلقة لا تنتهي:
 * رسم ⇒ `t` جديدة ⇒ تأثير ⇒ ضبط حالة ⇒ رسم…
 *
 * حدث هذا فعليًا في «مركز التحليل المالي»: طلب شبكة لا يتوقّف، وشريط فلاتر يهتزّ
 * لأن مؤشّر انشغال الزرّ يتأرجح فيتغيّر عرضه ويُعيد تدفّق الصفّ كلّه.
 *
 * `DICT` ثابت على مستوى الوحدة، فالدالّة لا تغلق إلا على `lang` — والتذكير عليها
 * وحدها صحيح تمامًا ولا يغيّر أي ناتج ترجمة.
 */
export function useT(): { t: (key: string, vars?: Record<string, string | number>) => string } {
  const { lang } = useUI();
  return useMemo(() => ({ t: (key: string, vars?: Record<string, string | number>) => t(key, lang, vars) }), [lang]);
}
